package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class TrackingFlipSessionTest {
 static final class Fake implements TrackingFlipSession.Port{boolean available=true,failStop,failStart,failHold,throwStart;int starts,stops,holds,releases;TrackingFlipSession.Sink sink;final List<TrackingFlipSession.Sink> all=new ArrayList<>();public boolean available(){return available;}public boolean start(TrackingFlipSession.Sink s){starts++;sink=s;all.add(s);if(throwStart)throw new IllegalStateException();return !failStart;}public boolean stop(){stops++;if(failStop)return false;sink=null;return true;}public void hold(long time){if(failHold)throw new IllegalStateException();holds++;assertEquals(TrackingFlipSession.PAUSE+60000,time);}public void release(){releases++;}}
 static final class Fixture implements TrackingFlipSession.Effects{long now=1000000000L;boolean live=true,failPause,failResume;int pauses,resumes;final Fake port=new Fake();final TrackingFlipSession session=new TrackingFlipSession(port,this,()->now);public boolean current(){return live;}public void pause(){pauses++;if(failPause)throw new IllegalStateException();}public void resume(){resumes++;if(failResume)throw new IllegalStateException();}void active(){session.active();}void sample(double z){now+=100000000;TrackingFlipSession.Sink sink=port.sink;if(sink!=null)sink.sample(now,now,0,0,z,true);}void hold(double z,int n){for(int i=0;i<n;i++)sample(z);}void flip(){hold(9.8,12);hold(-9.8,14);}void paused(){session.paused();}}
 @Test public void constructionHasNoSensorOrPauseEffects(){Fixture f=new Fixture();assertEquals(0,f.port.starts+f.pauses+f.resumes);}
 @Test public void unavailableInputLeavesManualFallback(){Fixture f=new Fixture();f.port.available=false;f.active();assertEquals(TrackingFlipSession.State.ERROR,f.session.state);assertTrue(f.session.issue.contains("No accelerometer"));assertEquals(0,f.pauses);}
 @Test public void activeFreshFlipRequestsExactlyOnePause(){Fixture f=new Fixture();f.active();f.flip();assertEquals(1,f.pauses);assertEquals(TrackingFlipSession.State.PAUSING,f.session.state);f.flip();assertEquals(1,f.pauses);}
 @Test public void cleanupAcknowledgmentRequiredBeforeGestureResume(){Fixture f=new Fixture();f.active();f.flip();f.hold(-9.8,12);f.hold(9.8,14);assertEquals(0,f.resumes);f.paused();assertEquals(TrackingFlipSession.State.PAUSED,f.session.state);}
 @Test public void explicitStableFaceUpResumesSameOwner(){Fixture f=new Fixture();f.active();f.flip();f.paused();f.hold(-9.8,12);f.hold(9.8,14);assertEquals(1,f.resumes);assertEquals(TrackingFlipSession.State.RESUMING,f.session.state);assertNull(f.port.sink);}
 @Test public void timerResumesAtFiveMinutesOnly(){Fixture f=new Fixture();f.active();f.flip();f.paused();long deadline=f.session.deadline;f.now=(deadline-1)*1000000;f.session.tick();assertEquals(0,f.resumes);f.now=deadline*1000000;f.session.tick();assertEquals(1,f.resumes);f.session.tick();assertEquals(1,f.resumes);}
 @Test public void faceDownCannotExtendPauseDeadline(){Fixture f=new Fixture();f.active();f.flip();f.paused();long deadline=f.session.deadline;f.hold(-9.8,100);assertEquals(deadline,f.session.deadline);}
 @Test public void manualPauseRevokesTimerAndOldGesture(){Fixture f=new Fixture();f.active();f.flip();f.paused();TrackingFlipSession.Sink old=f.port.sink;long due=f.session.deadline;f.session.manualPause();f.now=(due+100)*1000000;f.session.tick();old.sample(f.now,f.now,0,0,9.8,true);assertEquals(0,f.resumes);assertEquals(TrackingFlipSession.State.MANUAL_PAUSED,f.session.state);}
 @Test public void staleOwnerClosesAndNeverRevives(){Fixture f=new Fixture();f.active();TrackingFlipSession.Sink old=f.port.sink;f.live=false;f.sample(9.8);assertEquals(TrackingFlipSession.State.CLOSED,f.session.state);assertNull(f.port.sink);f.live=true;f.active();for(int n=0;n<30;n++)old.sample(f.now+n*100000000,f.now+n*100000000,0,0,n<13?9.8:-9.8,true);assertEquals(0,f.pauses);assertEquals(1,f.port.starts);}
 @Test public void lateTimerLeavesExplicitResumeFallback(){Fixture f=new Fixture();f.active();f.flip();f.paused();f.now=(f.session.deadline+TrackingFlipSession.LATE+1)*1000000;f.session.tick();assertEquals(0,f.resumes);assertEquals(TrackingFlipSession.State.ERROR,f.session.state);}
 @Test public void latePauseAckCannotRestartAfterDeadline(){Fixture f=new Fixture();f.active();f.flip();f.now=(f.session.deadline+TrackingFlipSession.LATE+1)*1000000;f.paused();assertEquals(0,f.resumes);assertEquals(TrackingFlipSession.State.ERROR,f.session.state);}
 @Test public void resumeRearmsFreshBaselineAndCannotImmediatelyPause(){Fixture f=new Fixture();f.active();f.flip();f.paused();f.now=f.session.deadline*1000000;f.session.tick();f.active();f.hold(-9.8,30);assertEquals(1,f.pauses);f.flip();assertEquals(2,f.pauses);}
 @Test public void failedHoldDoesNotPauseRecording(){Fixture f=new Fixture();f.port.failHold=true;f.active();f.flip();assertEquals(0,f.pauses);assertEquals(TrackingFlipSession.State.ERROR,f.session.state);}
 @Test public void failedCapturePauseDoesNotRetry(){Fixture f=new Fixture();f.failPause=true;f.active();f.flip();f.session.tick();assertEquals(1,f.pauses);assertEquals(0,f.resumes);assertEquals(TrackingFlipSession.State.ERROR,f.session.state);}
 @Test public void unregisterFailurePreventsResumeAndRetainsRetry(){Fixture f=new Fixture();f.active();f.flip();f.paused();f.port.failStop=true;f.now=f.session.deadline*1000000;f.session.tick();assertEquals(0,f.resumes);assertTrue(f.session.listening);f.port.failStop=false;f.session.tick();assertFalse(f.session.listening);assertNull(f.port.sink);}
 @Test public void registrationThrowKeepsRetryableStopHandle(){Fixture f=new Fixture();f.port.throwStart=true;f.port.failStop=true;f.active();assertTrue(f.session.listening);f.port.failStop=false;f.session.tick();assertFalse(f.session.listening);}
 @Test public void closeCancelsPendingResumeAndReleasesOnlyItsPort(){Fixture f=new Fixture();f.active();f.flip();f.paused();long due=f.session.deadline;f.session.close();f.now=due*1000000;f.session.tick();assertEquals(0,f.resumes);assertNull(f.port.sink);}
 @Test public void unreliableSensorNeverTriggersPause(){Fixture f=new Fixture();f.active();for(int n=0;n<40;n++){f.now+=100000000;f.port.sink.sample(f.now,f.now,0,0,n<15?9.8:-9.8,false);}assertEquals(0,f.pauses);assertTrue(f.session.issue.contains("unreliable"));}
}
